44	</main><script>
45	const form = document.getElementById('idea-form');
46	const titleInput = document.getElementById('f-title');
47	const descInput = document.getElementById('f-desc');
48	const scenarioInput = document.getElementById('f-scenario');
49	const errorBox = document.getElementById('error');
50	const successBox = document.getElementById('success');
51	const emptyNote = document.getElementById('empty');
52	const list = document.getElementById('ideas');
53	const EMPTY_TEXT = '还没有意见记录。';
54	const LOAD_FAILED_TEXT = '意见列表加载失败，请稍后刷新重试。';
55	// 首次列表请求的状态：loading（进行中）/ ready（成功）/ failed（失败）
56	let listState = 'loading';
57	function codePoints(text) { return Array.from(text).length; }
58	function showError(message) {
59	  errorBox.textContent = message;
60	  errorBox.hidden = false;
61	  successBox.hidden = true;
62	}
63	function renderIdea(idea) {
64	  const item = document.createElement('article');
65	  item.className = 'idea';
66	  const heading = document.createElement('h3');
67	  heading.textContent = idea.title;
68	  const desc = document.createElement('p');
69	  desc.className = 'pre';
70	  desc.textContent = idea.description;
71	  item.append(heading, desc);
72	  if (typeof idea.scenario === 'string' && idea.scenario.trim().length > 0) {
73	    const scenario = document.createElement('p');
74	    const label = document.createElement('strong');
75	    label.textContent = '使用场景：';
76	    const text = document.createElement('span');
77	    text.className = 'pre';
78	    text.textContent = idea.scenario;
79	    scenario.append(label, text);
80	    item.append(scenario);
81	  }
82	  const time = document.createElement('time');
83	  time.dateTime = idea.createdAt;
84	  const parsed = new Date(idea.createdAt);
85	  time.textContent = isNaN(parsed.getTime()) ? String(idea.createdAt) : parsed.toLocaleString();
86	  item.append(time);
87	  return item;
88	}
89	let remoteIdeas = [];
90	// 本页已确认保存的意见，最新提交的排在最前
91	const submittedIdeas = [];
92	function renderList() {
93	  // 以服务端标识 id 去重后合并：本页提交成功的意见在前，其后补入首次响应中的其他记录
94	  const seen = new Set();
95	  const ordered = [];
96	  for (const idea of submittedIdeas) {
97	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
98	  }
99	  for (const idea of remoteIdeas) {
100	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
101	  }
102	  list.replaceChildren(...ordered.map(renderIdea));
103	  if (listState === 'failed') {
104	    emptyNote.textContent = LOAD_FAILED_TEXT;
105	    emptyNote.hidden = false;
106	  } else if (listState === 'ready') {
107	    emptyNote.textContent = EMPTY_TEXT;
108	    emptyNote.hidden = ordered.length > 0;
109	  } else {
110	    // 首次列表仍在加载，不能把等待误报成没有记录
111	    emptyNote.hidden = true;
112	  }
113	}
114	async function loadIdeas() {
115	  try {
116	    const res = await fetch('/api/ideas');
117	    if (!res.ok) throw new Error('load failed');
118	    const data = await res.json();
119	    remoteIdeas = Array.isArray(data.ideas) ? data.ideas : [];
120	    listState = 'ready';
121	  } catch {
122	    listState = 'failed';
123	  }
124	  renderList();
125	}
126	function validate(title, description, scenario) {
127	  const trimmed = title.trim();
128	  if (!trimmed) return '标题不能为空。';
129	  if (codePoints(trimmed) > 120) return '标题最多 120 个字符。';
130	  if (!description.trim()) return '详细说明不能为空。';
131	  if (codePoints(description) > 5000) return '详细说明最多 5000 个字符。';
132	  if (codePoints(scenario) > 1000) return '使用场景最多 1000 个字符。';
133	  return null;
134	}
135	form.addEventListener('submit', async (event) => {
136	  event.preventDefault();
137	  errorBox.hidden = true;
138	  successBox.hidden = true;
139	  const title = titleInput.value;
140	  const description = descInput.value;
141	  const scenario = scenarioInput.value;
142	  const problem = validate(title, description, scenario);
143	  if (problem) { showError(problem); return; }
144	  let res;
145	  try {
146	    res = await fetch('/api/ideas', {
147	      method: 'POST',
148	      headers: { 'content-type': 'application/json' },
149	      body: JSON.stringify({ title, description, scenario })
150	    });
151	  } catch {
152	    showError('网络错误，提交未成功，请重试。');
153	    return;
154	  }
155	  let data = null;
156	  try { data = await res.json(); } catch { data = null; }
157	  if (!res.ok || !data || !data.idea) {
158	    showError(data && data.error ? '提交失败：' + data.error : '提交失败，请稍后重试。');
159	    return;
160	  }
161	  form.reset();
162	  successBox.textContent = '提交成功，你的意见已保存。';
163	  successBox.hidden = false;
164	  // 只把已确认保存的意见并入列表，随后统一渲染，避免与首次列表响应相互覆盖
165	  submittedIdeas.unshift(data.idea);
166	  renderList();
167	});
168	loadIdeas();
169	</script></html>`;
170	const args: string[] = process.argv.slice(2);
171	const help: string = `FeatureHarbor - 产品意见与公开路线图
172	Usage: node server.ts serve [--host ADDRESS] [--port PORT] [--data-dir DIRECTORY]
173	       node server.ts --help
174	Defaults: --host 127.0.0.1 --port 8080 --data-dir data
175	Port 0 selects an available port.
176	`;
177	if (args.length === 0 || args.includes('--help') || args.includes('-h')) {
178	  process.stdout.write(help);
179	  process.exit(args.length === 0 ? 2 : 0);
180	}
181	if (args.shift() !== 'serve') { console.error('Expected serve or --help'); process.exit(2); }
182	let host: string = '127.0.0.1';
183	let port: number = 8080;
184	let dataDir: string = 'data';
185	while (args.length) {
186	  const flag = args.shift();
187	  const value = args.shift();
188	  if (!value || !['--host', '--port', '--data-dir'].includes(flag ?? '')) {
189	    console.error('Each option must be --host, --port or --data-dir followed by a value'); process.exit(2);
190	  }
191	  if (flag === '--host') host = value;
192	  else if (flag === '--port') {
193	    if (!/^\d+$/.test(value) || Number(value) > 65535) { console.error('Port must be between 0 and 65535'); process.exit(2); }
194	    port = Number(value);
195	  } else dataDir = value;
196	}
197	mkdirSync(dataDir, { recursive: true });
198	const dataFile = join(dataDir, 'ideas.json');
199	try { writeFileSync(dataFile, '[]\n', { flag: 'wx' }); } catch (error) {
200	  if (!(error instanceof Error && 'code' in error && error.code === 'EEXIST')) throw error;
201	}
202	function respond(res: ServerResponse, status: number, value: unknown, options: { html?: boolean; allow?: string } = {}): void {
203	  const body = options.html ? String(value) : JSON.stringify(value);
204	  res.writeHead(status, { 'content-type': options.html ? 'text/html; charset=utf-8' : 'application/json; charset=utf-8',
205	    'content-length': Buffer.byteLength(body), ...(status === 405 ? { allow: options.allow ?? 'GET' } : {}) });
206	  res.end(body);
207	}
208	function codePoints(text: string): number {
209	  return Array.from(text).length;
210	}
211	function readIdeas(): unknown[] {
212	  const records: unknown = JSON.parse(readFileSync(dataFile, 'utf8'));
213	  if (!Array.isArray(records)) throw new Error('Invalid record list');
214	  return records;
215	}
216	function saveIdeas(records: unknown[]): void {
217	  const tempFile = `${dataFile}.tmp`;
218	  writeFileSync(tempFile, `${JSON.stringify(records, null, 2)}\n`);
219	  renameSync(tempFile, dataFile);
220	}
221	async function handleCreateIdea(req: IncomingMessage, res: ServerResponse): Promise<void> {
222	  const chunks: Buffer[] = [];
223	  let size = 0;
224	  for await (const chunk of req as AsyncIterable<Buffer>) {
225	    size += chunk.length;
226	    if (size > MAX_BODY_BYTES) {
227	      respond(res, 400, { error: '请求体过大' });
228	      req.destroy();
229	      return;
230	    }
231	    chunks.push(chunk);
232	  }
233	  let payload: unknown;
234	  try {
235	    payload = JSON.parse(Buffer.concat(chunks).toString('utf8'));
236	  } catch {
237	    respond(res, 400, { error: '请求体不是有效的 JSON' });
238	    return;
239	  }
240	  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
241	    respond(res, 400, { error: '请求体必须是 JSON 对象' });
242	    return;
243	  }
244	  const body = payload as Record<string, unknown>;
245	  for (const field of ['title', 'description'] as const) {
246	    if (body[field] === undefined) { respond(res, 400, { error: `缺少必填字段 ${field}` }); return; }
247	    if (typeof body[field] !== 'string') { respond(res, 400, { error: `字段 ${field} 必须是字符串` }); return; }
248	  }
249	  if (body.scenario !== undefined && typeof body.scenario !== 'string') {
250	    respond(res, 400, { error: '字段 scenario 必须是字符串' });
251	    return;
252	  }
253	  const title = (body.title as string).trim();
254	  const description = body.description as string;
255	  const scenario = typeof body.scenario === 'string' ? body.scenario : '';
256	  if (!title) { respond(res, 400, { error: '标题去掉首尾空白后不能为空' }); return; }
257	  if (codePoints(title) > MAX_TITLE) { respond(res, 400, { error: `标题最多 ${MAX_TITLE} 个字符` }); return; }
258	  if (!description.trim()) { respond(res, 400, { error: '详细说明必须包含非空白内容' }); return; }
259	  if (codePoints(description) > MAX_DESCRIPTION) { respond(res, 400, { error: `详细说明最多 ${MAX_DESCRIPTION} 个字符` }); return; }
260	  if (codePoints(scenario) > MAX_SCENARIO) { respond(res, 400, { error: `使用场景最多 ${MAX_SCENARIO} 个字符` }); return; }
261	  const idea = {
262	    id: randomUUID(),
263	    title,
264	    description,
265	    scenario,
266	    createdAt: new Date().toISOString(),
267	  };
268	  let records: unknown[];
269	  try {
270	    records = readIdeas();
271	  } catch {
272	    respond(res, 500, { error: '无法读取已有意见数据，未保存新意见' });
273	    return;
274	  }
275	  records.unshift(idea);
276	  try {
277	    saveIdeas(records);
278	  } catch {
279	    respond(res, 500, { error: '保存意见失败，请稍后重试' });
280	    return;
281	  }
282	  respond(res, 201, { idea });
283	}
284	const server = createServer((req: IncomingMessage, res: ServerResponse): void => {
285	  let route: string;
286	  try { route = new URL(req.url ?? '/', 'http://localhost').pathname; } catch { respond(res, 400, { error: 'invalid request path' }); return; }
287	  if (!['/', '/health', '/api/ideas'].includes(route)) { respond(res, 404, { error: 'not found' }); return; }
288	  if (route === '/api/ideas') {
289	    if (req.method === 'POST') {
290	      handleCreateIdea(req, res).catch(() => {
291	        if (!res.headersSent) respond(res, 500, { error: '提交意见失败，请稍后重试' });
292	      });
293	      return;
294	    }
295	    if (req.method !== 'GET') { respond(res, 405, { error: 'method not allowed' }, { allow: 'GET, POST' }); return; }
296	    try {
297	      respond(res, 200, { [RESOURCE]: readIdeas() });
298	    } catch { respond(res, 500, { error: 'unable to read ideas' }); }
299	    return;
300	  }
301	  if (req.method !== 'GET') { respond(res, 405, { error: 'method not allowed' }); return; }
302	  if (route === '/') { respond(res, 200, PAGE, { html: true }); return; }
303	  respond(res, 200, { status: 'ok', product: PRODUCT });
304	});
305	server.once('error', (error: Error): void => { console.error(error.message); process.exitCode = 1; });
306	server.listen(port, host, (): void => {
307	  const address = server.address();
308	  if (address && typeof address !== 'string') {
309	    const displayedHost = address.address.includes(':') ? `[${address.address}]` : address.address;
310	    console.log(`${PRODUCT} listening on http://${displayedHost}:${address.port}`);
311	  }
312	});
313	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
314	  process.on(signal, (): void => { server.close(() => { process.exitCode = 0; }); server.closeIdleConnections(); });
315	}
