1	import { spawn } from 'node:child_process';
2	import type { ChildProcess } from 'node:child_process';
3	import { mkdtempSync, rmSync } from 'node:fs';
4	import { tmpdir } from 'node:os';
5	import { dirname, join } from 'node:path';
6	import { fileURLToPath } from 'node:url';
7	
8	const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
9	const SERVER_TS = join(REPO_ROOT, 'server.ts');
10	
11	export interface StartedServer {
12	  origin: string;
13	  dataDir: string;
14	  stop: () => Promise<void>;
15	}
16	
17	// 启动一份真实的 server.ts（端口 0 自动选择可用端口，数据目录相互隔离）。
18	export function startServer(dataDir?: string): Promise<StartedServer> {
19	  const dir = dataDir ?? mkdtempSync(join(tmpdir(), 'featureharbor-'));
20	  const child: ChildProcess = spawn(
21	    process.execPath,
22	    [SERVER_TS, 'serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dir],
23	    { cwd: REPO_ROOT, stdio: ['ignore', 'pipe', 'pipe'] },
24	  );
25	  return new Promise((resolve, reject) => {
26	    let buffer = '';
27	    const onExit = (code: unknown): void => {
28	      reject(new Error(`测试服务提前退出，退出码 ${String(code)}`));
29	    };
30	    const onData = (chunk: Buffer): void => {
31	      buffer += chunk.toString('utf8');
32	      const match = buffer.match(/listening on (http:\/\/\S+)/);
33	      if (match) {
34	        child.removeListener('exit', onExit);
35	        child.stdout.off('data', onData);
36	        resolve({
37	          origin: match[1],
38	          dataDir: dir,
39	          stop: () =>
40	            new Promise<void>((done) => {
